import json

from inapppy import AppStoreValidator, InAppPyValidationError

bundle_id = "com.barexamdrills.app"
auto_retry_wrong_env_request = True

validator = AppStoreValidator(
    bundle_id, auto_retry_wrong_env_request=auto_retry_wrong_env_request
)

RECEIPT = ""
try:
    exclude_old_transactions = (
        True  # if True, include only the latest renewal transaction
    )
    validation_result = validator.validate(
        RECEIPT, None, exclude_old_transactions=exclude_old_transactions
    )
    print(json.dumps(validation_result, indent=4))
    if in_app := validation_result["receipt"]["in_app"]:
        in_app = sorted(in_app, key=lambda k: k["purchase_date_ms"])
        print(json.dumps(in_app, indent=4))

except InAppPyValidationError as ex:
    # handle validation error
    response_from_apple = (
        ex.raw_response
    )  # contains actual response from AppStore service.
    print(response_from_apple)
